// CompTIA A+ 220-1201 (Core 1) practice question bank.
// Format: [subject, question, correctAnswer, [distractors...], explanation]
// Order here does not matter — the app shuffles questions AND answer choices every run.
const Q = [];
const add = (s, list) => list.forEach(([q, a, w, e]) => Q.push({ s, q, a, w, e }));

